<script setup>
import {ref,onMounted,computed} from 'vue'
import {api} from '../main'
import {useChart} from '../chart'
const videos=ref([]),models=ref([]),modelId=ref(''),category=ref(''),level=ref(''),message=ref(''),editing=ref(null),chart=ref()
const blank=()=>({title:'',author:'',category:'生活',publishedAt:new Date().toISOString().slice(0,16),duration:30,views:0,likes:0,comments:0,shares:0,favorites:0,hashtags:0,hotBgm:false,publishPeriod:'晚'})
const form=ref(blank())
const filtered=computed(()=>videos.value.filter(v=>(!category.value||v.category===category.value)&&(!level.value||v.heatLevel===level.value)))
const option=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['真实播放','预测播放']},xAxis:{type:'category',data:videos.value.filter(v=>v.predictedViews!=null).map(v=>v.title)},yAxis:{type:'value'},series:[{name:'真实播放',type:'bar',data:videos.value.filter(v=>v.predictedViews!=null).map(v=>v.views)},{name:'预测播放',type:'bar',data:videos.value.filter(v=>v.predictedViews!=null).map(v=>v.predictedViews)}]}))
useChart(chart,option)
async function load(){videos.value=(await api.get('/videos')).data;models.value=(await api.get('/models')).data.filter(x=>x.status==='训练成功')}
async function save(){try{const payload={...form.value,publishedAt:form.value.publishedAt?.length===16?form.value.publishedAt+':00':form.value.publishedAt};if(editing.value)await api.put('/videos/'+editing.value,payload);else await api.post('/videos',payload);editing.value=null;form.value=blank();await load()}catch(e){message.value=e.response?.data?.error||e.message}}
function edit(v){editing.value=v.id;form.value={...v,publishedAt:v.publishedAt?.slice(0,16)}}
async function remove(v){if(confirm('删除视频 '+v.title+'？')){await api.delete('/videos/'+v.id);await load()}}
async function predict(v){try{await api.post('/videos/'+v.id+'/predict',{modelId:modelId.value});message.value='预测完成';await load()}catch(e){message.value=e.response?.data?.error||e.message}}
onMounted(load)
</script>
<template><section class="panel"><h2>{{editing?'编辑视频':'新增视频'}}</h2><div class="form"><label v-for="f in ['title','author','category','duration','views','likes','comments','shares','favorites','hashtags']" :key="f">{{f}}<input v-model="form[f]" :type="['title','author','category'].includes(f)?'text':'number'"></label><label>发布时间<input type="datetime-local" v-model="form.publishedAt"></label><label>发布时段<select v-model="form.publishPeriod"><option v-for="x in ['早','中','晚','凌晨']">{{x}}</option></select></label><label>热门 BGM<select v-model="form.hotBgm"><option :value="false">否</option><option :value="true">是</option></select></label></div><button @click="save">保存视频</button> <button v-if="editing" class="secondary" @click="editing=null;form=blank()">取消</button><p v-if="message" class="message">{{message}}</p></section><section class="panel" style="margin-top:16px"><div class="toolbar"><select v-model="category"><option value="">全部分类</option><option v-for="x in ['生活','美食','美妆','游戏','知识','舞蹈','剧情']">{{x}}</option></select><select v-model="level"><option value="">全部热度</option><option v-for="x in ['高热度','中热度','低热度']">{{x}}</option></select><select v-model="modelId"><option value="">选择预测模型</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></select></div><table><tr><th>标题</th><th>作者</th><th>分类</th><th>真实播放</th><th>预测播放</th><th>热度</th><th>操作</th></tr><tr v-for="v in filtered" :key="v.id"><td>{{v.title}}</td><td>{{v.author}}</td><td>{{v.category}}</td><td>{{v.views}}</td><td>{{v.predictedViews??'—'}}</td><td>{{v.heatLevel||'—'}}</td><td><button class="secondary" @click="edit(v)">编辑</button> <button :disabled="!modelId" @click="predict(v)">预测</button> <button class="danger" @click="remove(v)">删除</button></td></tr></table></section><section class="panel" style="margin-top:16px"><h2>真实播放与预测播放对比</h2><div ref="chart" class="chart"></div></section></template>
